/**
 * Lightweight HTML sanitizer for client-side use.
 *
 * Security model:
 * - RSC HTML from React's renderToString() is trusted (auto-escapes user content)
 * - Error messages and debug info are untrusted and must be escaped
 * - validateTrustedHtml() provides defense-in-depth for server HTML
 */
// Imported from the leaf category module, not error-registry.ts: that barrel
// composes ERROR_REGISTRY out of every category, and the composition keeps all
// 106 definitions alive in the RSC client bundle this file is part of.
import { SECURITY_VIOLATION } from "../../errors/error-registry/general.js";
/**
 * Patterns that RSC should never generate.
 * These indicate potential server compromise or misconfiguration.
 */
const SUSPICIOUS_PATTERN_SPECS = [
    { source: String.raw `<script[^>]*>[\s\S]*?<\/script>`, flags: "gi", name: "inline script" },
    { source: String.raw `javascript:`, flags: "gi", name: "javascript: URL" },
    { source: String.raw `\bon\w+\s*=`, flags: "gi", name: "event handler attribute" },
    { source: String.raw `data:\s*text\/html`, flags: "gi", name: "data: HTML URL" },
];
function createSuspiciousPatterns() {
    return SUSPICIOUS_PATTERN_SPECS.map(({ source, flags, name }) => ({
        pattern: new RegExp(source, flags),
        name,
    }));
}
export function escapeInlineJsonText(value) {
    return value
        .replace(/</g, "\\u003c")
        .replace(/>/g, "\\u003e")
        .replace(/&/g, "\\u0026")
        .replace(/\u2028/g, "\\u2028")
        .replace(/\u2029/g, "\\u2029");
}
export function jsonForInlineScript(value, space) {
    const serialized = JSON.stringify(value, null, space);
    if (serialized === undefined) {
        throw new TypeError("Inline script data must be JSON-serializable");
    }
    return escapeInlineJsonText(serialized);
}
export function buildTrustedHtmlValidatorScript() {
    const specsJson = jsonForInlineScript(SUSPICIOUS_PATTERN_SPECS);
    return `
    function isDevMode() {
      return window.__VERYFRONT_DEV__ === true;
    }

    const suspiciousHtmlPatterns = ${specsJson}.map(({ source, flags, name }) => ({
      pattern: new RegExp(source, flags),
      name,
    }));

    function validateTrustedHtml(html) {
      for (const { pattern, name } of suspiciousHtmlPatterns) {
        pattern.lastIndex = 0;
        if (!pattern.test(html)) continue;
        console.warn(\`[Security] Suspicious \${name} detected in server HTML\`);
        if (!isDevMode()) throw new Error(\`Potentially unsafe HTML: \${name} detected\`);
      }

      return html;
    }
  `.trim();
}
function isDevMode() {
    const g = globalThis;
    return g.__VERYFRONT_DEV__ === true || g.Deno?.env?.get?.("VERYFRONT_ENV") === "development";
}
/**
 * Validate trusted HTML from server (defense-in-depth).
 *
 * This is NOT a full sanitizer - server-rendered RSC content is trusted.
 * This catches scenarios where the server might be compromised or misconfigured.
 *
 * @param html - HTML string from server
 * @param options - Validation options
 * @returns The original HTML if valid
 * @throws Error if suspicious patterns detected in strict mode or production
 */
export function validateTrustedHtml(html, options = {}) {
    const { allowInlineScripts = false, strict = false, warn = true } = options;
    for (const { pattern, name } of createSuspiciousPatterns()) {
        if (allowInlineScripts && name === "inline script")
            continue;
        pattern.lastIndex = 0;
        if (!pattern.test(html))
            continue;
        if (warn)
            console.warn(`[Security] Suspicious ${name} detected in server HTML`);
        if (strict || !isDevMode()) {
            throw SECURITY_VIOLATION.create({ detail: `Potentially unsafe HTML: ${name} detected` });
        }
    }
    return html;
}
/**
 * Create an error display element safely using DOM APIs.
 * Use this instead of innerHTML for displaying error messages.
 */
export function createErrorDisplay(options) {
    const { title, message, details, style } = options;
    const container = document.createElement("div");
    Object.assign(container.style, {
        color: "red",
        border: "2px solid red",
        padding: "10px",
        margin: "5px",
        fontFamily: "monospace",
        fontSize: "14px",
        backgroundColor: "#fff0f0",
        ...style,
    });
    const titleEl = document.createElement("strong");
    titleEl.textContent = title;
    container.append(titleEl, document.createElement("br"));
    const messageEl = document.createElement("span");
    messageEl.textContent = message;
    container.appendChild(messageEl);
    if (!details)
        return container;
    const detailsEl = document.createElement("pre");
    detailsEl.style.cssText = "margin: 5px 0; white-space: pre-wrap; word-break: break-word;";
    detailsEl.textContent = details;
    container.append(document.createElement("br"), detailsEl);
    return container;
}
